actions.script:
// Case-insensitive keyword filter applied in Groovy, not SQL LIKE - H2's default
// collation is case-sensitive (confirmed: "robot" would not match "Industrial
// Robot" via a raw LIKE condition), and the agent calling this tool cannot be
// expected to guess the exact casing used in a stored description.
String kw = keyword ? (keyword as String).toLowerCase() : null

List dtList = ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'DeviceType').orderBy('enumId').list()
if (kw) dtList = dtList.findAll { (it.description as String)?.toLowerCase()?.contains(kw) }
deviceTypes = dtList.collect { [enumId: it.enumId, parentEnumId: it.parentEnumId, description: it.description] }

List acList = ec.entity.find('moqui.basic.Enumeration').condition('enumTypeId', 'AssetClass').orderBy('enumId').list()
if (kw) acList = acList.findAll { (it.description as String)?.toLowerCase()?.contains(kw) }
assetClasses = acList.collect { [enumId: it.enumId, parentEnumId: it.parentEnumId, description: it.description] }

List catList = ec.entity.find('mantle.product.category.ProductCategory')
        .condition('productCategoryTypeEnumId', 'PctRegulatory').orderBy('productCategoryId').list()
if (kw) catList = catList.findAll { (it.description as String)?.toLowerCase()?.contains(kw) }
productCategories = catList.collect { cat ->
    List groupAppls = ec.entity.find('mantle.product.feature.ProductCategoryFeatGrpAppl')
            .condition('productCategoryId', cat.productCategoryId).list()
    List groups = groupAppls.collect { ga ->
        def group = ec.entity.find('mantle.product.feature.ProductFeatureGroup')
                .condition('productFeatureGroupId', ga.productFeatureGroupId).one()
        List featAppls = ec.entity.find('mantle.product.feature.ProductFeatureGroupAppl')
                .condition('productFeatureGroupId', ga.productFeatureGroupId).orderBy('sequenceNum').list()
        List features = featAppls.collect { fa ->
            def feat = ec.entity.find('mantle.product.feature.ProductFeature')
                    .condition('productFeatureId', fa.productFeatureId).one()
            [productFeatureId: feat?.productFeatureId, description: feat?.description]
        }
        [productFeatureGroupId: group?.productFeatureGroupId, description: group?.description, features: features]
    }
    [productCategoryId: cat.productCategoryId, categoryName: cat.categoryName,
            description: cat.description, featureGroups: groups]
}

// norm-derived feature types that exist as flat evidence (no category/group
// traversal) - real gap found and fixed 2026-07-09: these were completely absent
// from this tool's output before, even though check#DeviceSafetyExposure already
// reads them at runtime.
List normFeatureTypes = ['PftSafetyFunction', 'PftSecurityCapability']
List allNormFeatures = ec.entity.find('mantle.product.feature.ProductFeature')
        .condition('productFeatureTypeEnumId', 'in', normFeatureTypes)
        .orderBy('productFeatureId').list()
Set groupedFeatureIds = ec.entity.find('mantle.product.feature.ProductFeatureGroupAppl').list()
        *.productFeatureId as Set
List standalone = allNormFeatures.findAll { !groupedFeatureIds.contains(it.productFeatureId) }
if (kw) standalone = standalone.findAll { (it.description as String)?.toLowerCase()?.contains(kw) }
standaloneFeatures = standalone.collect {
    [productFeatureId: it.productFeatureId, productFeatureTypeEnumId: it.productFeatureTypeEnumId,
            description: it.description]
}

import groovy.json.JsonOutput

if (!deviceTypeEnumId && !assetClassEnumId && !(productCategoryIds as List)) {
    ec.message.addError("At least one of deviceTypeEnumId, assetClassEnumId, or productCategoryIds is required.")
    return
}

def runValue = ec.entity.makeValue('moqui.math.MathModelRun')
        .setAll([mathModelId: 'MM_PRODUCT_CLASSIFICATION',
                 startTime: ec.user.nowTimestamp,
                 parameters: JsonOutput.toJson([productId: productId, deviceTypeEnumId: deviceTypeEnumId,
                         assetClassEnumId: assetClassEnumId, productCategoryIds: productCategoryIds,
                         rationale: rationale]),
                 hasError: 'N'])
runValue.setSequencedIdPrimary()
runValue.create()
mathModelRunId = runValue.mathModelRunId

try {
    int assetsUpdatedCount = 0
    int devicesUpdatedCount = 0
    List assets = ec.entity.find('mantle.product.asset.Asset').condition('productId', productId).list()
    assets.each { asset ->
        if (assetClassEnumId) {
            ec.entity.find('mantle.product.asset.Asset').condition('assetId', asset.assetId).one()
                    .setAll([classEnumId: assetClassEnumId]).update()
            assetsUpdatedCount++
        }
        if (deviceTypeEnumId) {
            // Device is cache="true" (moqui-device/entity/DeviceEntities.xml) - a
            // cached find returns an immutable value; must re-find with
            // .useCache(false) before update, same class of bug as the earlier
            // Parameter cache-immutability fix in check#ThreatScenarioRisk.
            def deviceValue = ec.entity.find('moqui.device.Device').condition('assetId', asset.assetId).useCache(false).one()
            if (deviceValue) {
                ec.entity.find('moqui.device.Device').condition('deviceId', deviceValue.deviceId).useCache(false).one()
                        .setAll([deviceTypeEnumId: deviceTypeEnumId]).update()
                devicesUpdatedCount++
            }
        }
    }
    assetsUpdated = assetsUpdatedCount
    devicesUpdated = devicesUpdatedCount

    int categoriesEnsuredCount = 0
    (productCategoryIds as List ?: []).each { catId ->
        def existingMember = ec.entity.find('mantle.product.category.ProductCategoryMember')
                .condition('productCategoryId', catId).condition('productId', productId).one()
        if (!existingMember) {
            ec.service.sync().name('create#mantle.product.category.ProductCategoryMember')
                    .parameters([productCategoryId: catId, productId: productId,
                            fromDate: ec.user.nowTimestamp, comments: rationale]).call()
            categoriesEnsuredCount++
        }
    }
    categoriesEnsured = categoriesEnsuredCount

    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, results: JsonOutput.toJson(
                    [assetsUpdated: assetsUpdatedCount, devicesUpdated: devicesUpdatedCount,
                     categoriesEnsured: categoriesEnsuredCount])])
            .update()
} catch (Throwable t) {
    ec.entity.find('moqui.math.MathModelRun').condition('mathModelRunId', mathModelRunId).one()
            .setAll([endDate: ec.user.nowTimestamp, hasError: 'Y', errors: t.toString()])
            .update()
    throw t
}
